import{_ as e,o,c as a,ah as r}from"./chunks/framework.D7md08E-.js";const c=JSON.parse('{"title":"2. LSC Series Controller Communication Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Communication_Protocol.md","filePath":"docs/2_Communication_Protocol.md"}'),n={name:"docs/2_Communication_Protocol.md"};function d(h,t,i,s,l,m){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-lsc-series-controller-communication-protocol" tabindex="-1">2. LSC Series Controller Communication Protocol <a class="header-anchor" href="#_2-lsc-series-controller-communication-protocol" aria-label="Permalink to &quot;2. LSC Series Controller Communication Protocol&quot;">​</a></h1><p>Serial communication, baud rate: 9600</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>Length</td><td>Cmd</td><td>Prm 1…Prm N</td></tr></tbody></table><p>Frame Header: Two consecutive bytes 0x55 0x55 indicate the start of a valid data packet.</p><p>Data Length: Equals the number of parameters N plus one byte for the command and one byte for the data length field itself. Formula: Length = N + 2</p><p>Command (Cmd): The control command code.</p><p>Parameters (Prm): Additional control data required for the command.</p><h2 id="_2-1-sending-data-from-the-user-to-the-controller" tabindex="-1">2.1 Sending Data from the User to the Controller <a class="header-anchor" href="#_2-1-sending-data-from-the-user-to-the-controller" aria-label="Permalink to &quot;2.1 Sending Data from the User to the Controller&quot;">​</a></h2><p>The TX pin of the user&#39;s device should be connected to the controller&#39;s RX pin. The controller and the user&#39;s system must share a common ground (GND). When the controller receives correct data, the <strong>blue LED2</strong> will blink once, indicating successful reception. If incorrect data is sent, <strong>LED2</strong> will remain steadily lit. The buzzer will emit two quick &quot;<strong>beep-beep</strong>&quot; sounds to indicate a data error.</p><p>(1) Command Name: CMD_ SERVO_MOVE, Command Value: 3, Data Length (Length):</p><p><strong>Description:</strong> Controls the movement of any number of servos. Length = (Number of Servos × 3) + 5</p><p>Prm1: Number of servos to control</p><p>Prm2: Time (low byte)</p><p>Prm3: Time (high byte)</p><p>Prm4: Servo ID</p><p>Prm5: Angle position (low byte)</p><p>Prm6: Angle position (high byte)</p><p>Parameters ...: Additional servos follow the same pattern as Prm4–Prm6 for different servo IDs.</p><p>Examples:</p><p>① Control servo ID 1 to move to position 2000 within 1000 ms:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x08</td><td>0x03</td><td>0x01 0xE8 0x03 0x01 0xD0 0x07</td></tr></tbody></table><p>② Control servo 2 to move to position 1200 within 800 ms, and servo 9 to move to position 2300 within 800 ms:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x0B</td><td>0x03</td><td>0x02 0x20 0x03 0x02 0xB0 0x04 0x09 0xFC 0x08</td></tr></tbody></table><p>(2) Command Name: CMD _ACTION_GROUP_RUN, Command Value: 6, Data Length (Length): 5</p><p><strong>Description:</strong> Controls the execution of an action group. The action group must already be downloaded to the controller. You can specify the number of times the action group runs. If you want the action group to run indefinitely, set the repeat count parameter to 0.</p><p>Prm1: Action group ID to run</p><p>Prm2: Number of times to run (low byte)</p><p>Prm3: Number of times to run (high byte)</p><p>Examples:</p><p>① Control Action Group ID 8 to run once:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x06</td><td>0x08 0x01 0x00</td></tr></tbody></table><p>② Control Action Group ID 2 to run indefinitely:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x06</td><td>0x02 0x00 0x00</td></tr></tbody></table><p>(3) Command Name: CMD _ACTION_GROUP_STOP, Command Value: 7, Data Length (Length): 2</p><p><strong>Description:</strong> Stops the currently running action group. If no action group is running, sending this command will have no effect.</p><p>Parameters: None</p><p>Examples:</p><p>① Stop the currently running action group:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x02</td><td>0x07</td><td>None</td></tr></tbody></table><p>(4) Command Name: CMD_ACTION_GROUP _SPEED, Command Value: 11, Data Length (Length): 5</p><p><strong>Description:</strong> Adjusts the speed of an action group in percentage format. For example: setting speed to 200 means 200% of the original speed (twice as fast). If the Action Group ID is set to 0xFF, all downloaded action groups will have their speeds adjusted.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>The speed adjustment will not be saved after power-off. It must be set again after reboot.</li><li>Servos have a maximum physical rotation speed. Setting the speed to a multiple higher than their limit will not increase the actual movement speed.</li></ul></section><p>Parameter 1: Action Group ID</p><p>Parameter 2: Speed percentage (Low byte)</p><p>Parameter 3: Speed percentage (High byte)</p><p><strong>Examples:</strong></p><p>① Control Action Group ID 8 to run at 50% speed:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x0B</td><td>0x08 0x32 0x00</td></tr></tbody></table><p>② Adjust all downloaded action groups (0xFF) to 300% speed:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x0B</td><td>0xFF 0x2C 0x01</td></tr></tbody></table><p>(5) Command Name: CMD_GET_BATTERY_VOLTAGE, Command Value: 15, Data Length (Length): 2</p><p><strong>Description:</strong> Requests the battery voltage of the controller, in millivolts (mV). After this command is sent, the controller immediately returns a data packet containing two parameter bytes.</p><p>Parameters: None</p><p>Send Format:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x02</td><td>0x0F</td><td>None</td></tr></tbody></table><p>Return: The controller&#39;s response contains: Parameter 1 – Low 8 bits of the voltage value, Parameter 2 – High 8 bits of the voltage value</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x04</td><td>0x0F</td><td>0x4C 0x1D</td></tr></tbody></table><h2 id="_2-2-data-sent-by-the-controller-to-user" tabindex="-1">2.2 Data Sent by the Controller to User <a class="header-anchor" href="#_2-2-data-sent-by-the-controller-to-user" aria-label="Permalink to &quot;2.2 Data Sent by the Controller to User&quot;">​</a></h2><p>During operation, when the controller&#39;s status changes, it will actively send data to the user via the serial port. For example, when an action group finishes running. There are multiple ways to operate the controller, such as using a PS2 controller, connecting via a Bluetooth module, or using the user&#39;s custom serial interface. Hence, it is necessary for different control methods to be aware of the current status of the controller to facilitate proper management and operation. The following are the instructions that the controller returns to the user.</p><p>(1) Command Name: CMD _ACTION_GROUP_RUN, Command Value: 6, Data Length (Length): 5</p><p><strong>Description:</strong> When the controller starts running an action group, it immediately sends data with parameter information. The return data format is the same as the format used by the user to control the action group run command.</p><p>Prm1: Action group ID to run</p><p>Prm2: Number of times to run (low byte)</p><p>Prm3: Number of times to run (high byte)</p><p>Examples:</p><p>When action group 8 is running and is set to run once, the controller returns the following data packet to the user:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x06</td><td>0x08 0x01 0x00</td></tr></tbody></table><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Even if the user initiates the action group run via the serial port, once the controller starts executing the command, it will immediately send back this status message via the serial port.</p></section><p>(2) Command Name: CMD _ACTION_GROUP_STOP, Command Value: 7, Data Length (Length): 2</p><p><strong>Description:</strong> When a running action group is forcibly stopped by another method, for example, via the wireless controller or by the user sending a stop command, this command is returned.</p><p>The return data format is the same as the format used by the user to stop the action group running command.</p><p>Parameters: None Examples:</p><p>① When an action group that is currently running is forcibly stopped, the following data is returned:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x02</td><td>0x07</td><td>None</td></tr></tbody></table><p>(3) Command Name: CMD _ACTION_GROUP_COMPLETE, Command Value: 8, Data Length (Length): 5</p><p><strong>Description:</strong> This command is returned when an action group finishes running naturally, which was not forcefully stopped, but ended because its programmed duration was reached.</p><p>Prm1: Action group ID to run</p><p>Prm2: Number of times to run (low byte)</p><p>Prm3: Number of times to run (high byte)</p><p>Examples:</p><p>When action group No. 8 is set to run once and finishes naturally, the controller returns the following data to the user:</p><table tabindex="0"><thead><tr><th>Frame Header</th><th>Data Length</th><th>Command</th><th>Parameters</th></tr></thead><tbody><tr><td>0x55 0x55</td><td>0x05</td><td>0x08</td><td>0x08 0x01 0x00</td></tr></tbody></table>',82)])])}const u=e(n,[["render",d]]);export{c as __pageData,u as default};
